Ultrasonic sonar(9, 10);
CsvLog logger("seconds,cm");
Every measure(1000);

void setup() {
  sonar.begin();
  logger.begin(9600);
}

void loop() {
  if (!measure.ready()) return;
  logger.row(millis() / 1000, sonar.cm());
}

const float SENSOR_TO_BOTTOM_CM = 150, SENSOR_TO_FULL_CM = 20;
TankLevel tank(sonar, SENSOR_TO_BOTTOM_CM, SENSOR_TO_FULL_CM);
...
logger.row(millis() / 1000, tank.percent());

if (level >= 95) {
  if (!alarm.running()) alarm.start(Alarm::FAST);
} else if (level <= 10) {
  if (!alarm.running()) alarm.start(Alarm::SLOW);
} else {
  alarm.stop();
}

int level = tank.percent();
if (level < 0) {
  if (++sensorFails >= 3) alarm.start(Alarm::SOS);
  logger.row(millis() / 1000, -1);
  return;
}
sensorFails = 0;

Relay pump(7, true, 30UL * 60UL * 1000UL);
...
if (level >= 95) {
  pump.off();
  if (!alarm.running()) alarm.start(Alarm::FAST);
}
...
if (pump.tripped()) alarm.start(Alarm::SOS);
